// Answers the tokens above first, then asks the real store.
export function withXrpDevTokens<T extends FrameworkCryptoAssetsStore>(store: T): T {
  return {
    ...store,
    findTokenById: async (id: string) =>
      XRP_DEV_TOKENS.find(token => token.id === id) ?? store.findTokenById(id),
    findTokenByAddressInCurrency: async (
      address: string,
      currencyId: string,
      tokenIdentifier?: string,
    ) =>
      XRP_DEV_TOKENS.find(
        token =>
          token.parentCurrencyId === currencyId &&
          token.contractAddress === address &&
          token.tokenIdentifier === tokenIdentifier,
      ) ?? store.findTokenByAddressInCurrency(address, currencyId, tokenIdentifier),
  };
}
